create table xxcus.xxfnd_storage_config (
    storage_config_id     number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    entity_name           varchar2(60 byte),
    category_code         varchar2(30 byte),
    storage_type          varchar2(30 byte) not null enable,
    endpoint_code         varchar2(30 byte) not null enable,
    folder_path_template  varchar2(1000 byte) default '/#ENTITY_NAME#/#PK1_VALUE#' not null enable,
    ucm_security_group    varchar2(100 byte),
    ucm_doc_type          varchar2(100 byte),
    ucm_doc_account       varchar2(100 byte),
    sharepoint_site_id    varchar2(500 byte),
    sharepoint_drive_id   varchar2(500 byte),
    priority              number default 100 not null enable,
    enabled_flag          varchar2(1 byte) default 'Y' not null enable,
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxfnd_storage_config
    add constraint xxfnd_storage_config_ck1
        check ( storage_type in ( 'UCM', 'SHAREPOINT' ) ) enable;

alter table xxcus.xxfnd_storage_config
    add constraint xxfnd_storage_config_ck2
        check ( ( storage_type = 'UCM'
                  and ucm_security_group is not null )
                or ( storage_type = 'SHAREPOINT'
                     and sharepoint_site_id is not null
                     and sharepoint_drive_id is not null ) ) enable;

alter table xxcus.xxfnd_storage_config
    add constraint xxfnd_storage_config_ck3
        check ( enabled_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxfnd_storage_config
    add constraint xxfnd_storage_config_pk primary key ( storage_config_id )
        using index enable;


